<script setup lang="ts">
/**
 * A Button preset that starts and stops recording (`design/components/record-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/record-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { agentMember, agentPress, clockTime } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/record-button.module.css'
import Button from './Button.vue'

export interface RecordButtonProps {
  disabled?: boolean
  /**
   * The seconds the application has recorded, drawn as m:ss beside the mark while recording. It
   * is not announced, because a time read out every second interrupts everything else.
   */
  elapsed?: number
  /**
   * The Button's name while not recording: "Record a voice message".
   */
  label: string
  /**
   * The input level from 0 to 1, drawn as the size of the mark's halo while recording. It is
   * never the only sign of recording: the glyph, the frame, the name and the time say it too.
   */
  level?: number
  /**
   * The locale the time's numerals are written in; the page's own when absent.
   */
  locale?: string
  /**
   * The application is recording. The member draws it and never sets it.
   */
  recording?: boolean
  /**
   * Button's sizes without `lg`. A record control sits beside a field, not as a page's main
   * action.
   */
  size?: 'sm' | 'md'
  /**
   * The Button's name while recording: "Stop recording".
   */
  stopLabel: string
}

defineOptions({ name: 'RecordButton', inheritAttrs: false })

const props = withDefaults(defineProps<RecordButtonProps>(), {
  disabled: false,
  recording: false,
  size: 'md',
})
const emit = defineEmits<{ start: []; stop: [] }>()
const root = useTemplateRef<HTMLElement>('root')
const share = computed(() =>
  props.level !== undefined && Number.isFinite(props.level)
    ? Math.min(1, Math.max(0, props.level))
    : 0,
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'RecordButton',
    element: () => root.value?.querySelector('button'),
    state: () => ({ recording: props.recording, disabled: props.disabled }),
    actions: {
      stop: () =>
        (() => {
          if (!props.recording) throw new Error('Nothing is recording.')
          agentPress(root.value?.querySelector('button'))
        })(),
    },
    withholds: () => root.value,
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <span
    ref="root"
    :class="styles.root"
    :data-state="recording ? 'recording' : undefined"
    :data-size="size"
    data-member="record-button"
  >
    <!-- meter -->
    <span v-if="recording" :class="styles.meter" data-record-button-part="meter">
      <!-- mark -->
      <span
        :class="styles.mark"
        :style="{ '--pm-record-button-level': share }"
        aria-hidden="true"
      />
      <!-- elapsed -->
      <span v-if="elapsed !== undefined" :class="styles.elapsed">
        {{ clockTime(elapsed ?? 0, locale) }}
      </span>
    </span>
    <Button
      :variant="recording ? 'outline' : 'ghost'"
      tone="neutral"
      :size="size"
      :iconOnly="true"
      :icon="recording ? 'stop' : 'record'"
      :label="recording ? stopLabel : label"
      :disabled="disabled"
      @click="recording ? emit('stop') : emit('start')"
    />
  </span>
</template>
